package com.aicommerce.platform.delivery.application.port;
import java.math.BigDecimal; import java.util.UUID; import com.aicommerce.platform.delivery.domain.PlatformBudgetType;
public record PlatformBudgetMutationCommand(PlatformCommandIdentity identity,UUID platformAdSetUuid,String existingExternalId,long expectedEntityVersion,PlatformBudgetType budgetType,String currency,BigDecimal previousBudgetAmount,BigDecimal newBudgetAmount){public PlatformBudgetMutationCommand{PlatformContractSupport.req(identity);PlatformContractSupport.req(platformAdSetUuid);existingExternalId=PlatformContractSupport.safe(existingExternalId);PlatformContractSupport.req(budgetType);previousBudgetAmount=PlatformContractSupport.money(previousBudgetAmount);newBudgetAmount=PlatformContractSupport.money(newBudgetAmount);if(expectedEntityVersion<0||!"TWD".equals(currency)||previousBudgetAmount.compareTo(newBudgetAmount)==0)throw PlatformContractSupport.invalid();BigDecimal max=budgetType==PlatformBudgetType.DAILY?new BigDecimal("100"):new BigDecimal("300");if(newBudgetAmount.compareTo(max)>0)throw PlatformContractSupport.invalid();}}
